const sdkProperty = (value: unknown, key: PropertyKey): unknown => {
  if (typeof value !== "object" || value === null) {
    return null;
  }
  const descriptor = Option.liftThrowable(Object.getOwnPropertyDescriptor)(
    value,
    key
  );
  return Option.match(descriptor, {
    onNone: () => null,
    onSome: (property) => {
      if (property === undefined || !("value" in property)) {
        return null;
      }
      const propertyValue: unknown = property.value;
      return propertyValue;
    },
  });
};

const makeSdkObservedFailure = (
  operation: PhotonSdkOperation,
  phase: PhotonSdkPhase,
  failure: unknown
) => {
  const nestedCause = sdkProperty(failure, "cause");
  const transportStatus = sdkProperty(nestedCause, "code");
  const retryable = sdkProperty(failure, "retryable");
  return new PhotonSdkObservedFailure({
    operation,
    phase,
    transportStatus:
      typeof transportStatus === "number" &&
      Number.isSafeInteger(transportStatus) &&
      transportStatus >= 100 &&
      transportStatus <= 599
        ? transportStatus
        : "unknown",
    retryable: typeof retryable === "boolean" ? retryable : "unknown",
  });
};

const observeSdkFailure = (failure: PhotonSdkObservedFailure) =>
  Effect.logError("PhotonSdkOperationFailure", failure);

const observeSdkSuccess = (
  operation: PhotonSdkOperation,
  phase: PhotonSdkPhase
) =>
  Effect.logInfo("PhotonSdkOperationSuccess", {
    provider: "photon",
    operation,
    phase,
  });

const liveFactory: PhotonSdkFactory = {
  acquire: async (config) => {
    const app = await Spectrum({
      projectId: config.projectId,
      projectSecret: Redacted.value(config.projectSecret),
      // @ts-expect-error Spectrum 12.3.0 models an absent events property as
      // incompatible with its own AnyPlatformDef under exact optional types.
      providers: [imessage.config()],
      telemetry: false,
      options: { logLevel: "warn" },
    });
    const provider = imessage(app);
    return {
      resolveDirectSpace: async (participantId) => {
        const participant = await provider.user(participantId);
        const space = await provider.space.create(participant);
        return {
          sendMessage: (text) => space.send(text),
          setPresence: (action) =>
            action === "start" ? space.startTyping() : space.stopTyping(),
        };
      },
      stop: () => app.stop(),
    };
  },
};

export const provePhotonSdkLifecycle = (config: PhotonConfig) =>
  Effect.acquireUseRelease(
    Effect.tryPromise({
      try: () => liveFactory.acquire(config),
      catch: () =>
        new PhotonLifecycleError({
          operation: "acquire",
          reason: "unavailable",
        }),
    }),
    () => Effect.void,
    (resource) =>
      Effect.tryPromise({
        try: () => resource.stop(),
        catch: () =>
          new PhotonLifecycleError({
            operation: "release",
            reason: "unavailable",
          }),
      })
  );

const releasePhotonResource = (
  resource: PhotonSdkResource,
  operation: PhotonSdkOperation
) =>
  Effect.tryPromise({
    try: () => resource.stop(),
    catch: (failure) => makeSdkObservedFailure(operation, "release", failure),
  }).pipe(
    Effect.tap(() => observeSdkSuccess(operation, "release")),
    Effect.tapError(observeSdkFailure),
    Effect.mapError(
      () =>
        new PhotonLifecycleError({
          operation: "release",
          reason: "unavailable",
        })
    ),
    Effect.tapError(() =>
      Effect.logError("PhotonLifecycleError", {
        operation: "release",
        reason: "unavailable",
      })
    ),
    Effect.ignore
  );

const withPhotonResource = <A, E>(
  config: PhotonConfig,
  factory: PhotonSdkFactory,
  operation: PhotonSdkOperation,
  use: (resource: PhotonSdkResource) => Effect.Effect<A, E>
) =>
  Effect.acquireUseRelease(
    Effect.tryPromise({
      try: () => factory.acquire(config),
      catch: (failure) => makeSdkObservedFailure(operation, "acquire", failure),
    }).pipe(
      Effect.tap(() => observeSdkSuccess(operation, "acquire")),
      Effect.tapError(observeSdkFailure),
      Effect.mapError(
        () =>
          new ChannelUnavailableError({
            provider: "photon",
            operation,
            reason: "transport",
            retry: "backoff",
          })
      )
    ),
    use,
    (resource) => releasePhotonResource(resource, operation)
  );

export const layerClient = (config: PhotonConfig, factory: PhotonSdkFactory) =>
  Layer.succeed(
    PhotonClient,
    PhotonClient.of({
      sendMessage: Effect.fn("PhotonClient.sendMessage")(
        (participantId, text) =>
          withPhotonResource(config, factory, "sendMessage", (resource) =>
            Effect.gen(function* sendPhotonMessage() {
              const space = yield* Effect.tryPromise({
                try: () => resource.resolveDirectSpace(participantId),
                catch: (failure) =>
                  makeSdkObservedFailure(
                    "sendMessage",
                    "resolveDirectSpace",
                    failure
                  ),
              }).pipe(
                Effect.tap(() =>
                  observeSdkSuccess("sendMessage", "resolveDirectSpace")
                ),
                Effect.tapError(observeSdkFailure),
                Effect.mapError(
                  () =>
                    new ChannelUnavailableError({
                      provider: "photon",
                      operation: "sendMessage",
                      reason: "transport",
                      retry: "backoff",
                    })
                )
              );
              const result = yield* Effect.tryPromise({
                try: () => space.sendMessage(text),
                catch: (failure) =>
                  makeSdkObservedFailure("sendMessage", "send", failure),
              }).pipe(
                Effect.tap(() => observeSdkSuccess("sendMessage", "send")),
                Effect.tapError(observeSdkFailure),
                Effect.mapError(
                  () =>
                    new ChannelDeliveryUncertainError({
                      provider: "photon",
                      operation: "sendMessage",
                      reason: "uncertain",
                      retry: "readbackRequired",
                    })
                )
              );
              return yield* Schema.decodeUnknownEffect(PhotonSdkSendResult)({
                id: sdkProperty(result, "id"),
              }).pipe(
                Effect.mapError(
                  () =>
                    new ChannelProviderRejectedError({
                      provider: "photon",
                      operation: "sendMessage",
                      reason: "invalidPayload",
                      retry: "never",
                    })
                )
              );
            })
          )
      ),
      setPresence: Effect.fn("PhotonClient.setPresence")(
        (participantId, action) =>
          withPhotonResource(config, factory, "setPresence", (resource) =>
            Effect.gen(function* setPhotonPresence() {
              const space = yield* Effect.tryPromise({
                try: () => resource.resolveDirectSpace(participantId),
                catch: (failure) =>
                  makeSdkObservedFailure(
                    "setPresence",
                    "resolveDirectSpace",
                    failure
                  ),
              }).pipe(
                Effect.tap(() =>
                  observeSdkSuccess("setPresence", "resolveDirectSpace")
                ),
                Effect.tapError(observeSdkFailure),
                Effect.mapError(
                  () =>
                    new ChannelUnavailableError({
                      provider: "photon",
                      operation: "setPresence",
                      reason: "transport",
                      retry: "backoff",
                    })
                )
              );
              yield* Effect.tryPromise({
                try: () => space.setPresence(action),
                catch: (failure) =>
                  makeSdkObservedFailure(
                    "setPresence",
                    action === "start" ? "startTyping" : "stopTyping",
                    failure
                  ),
              }).pipe(
                Effect.tap(() =>
                  observeSdkSuccess(
                    "setPresence",
                    action === "start" ? "startTyping" : "stopTyping"
                  )
                ),
                Effect.tapError(observeSdkFailure),

              }).pipe(
                Effect.tap(() =>
                  observeSdkSuccess("setPresence", "resolveDirectSpace")
                ),
                Effect.tapError(observeSdkFailure),
                Effect.mapError(
                  () =>
                    new ChannelUnavailableError({
                      provider: "photon",
                      operation: "setPresence",
                      reason: "transport",
                      retry: "backoff",
                    })
                )
              );
              yield* Effect.tryPromise({
                try: () => space.setPresence(action),
                catch: (failure) =>
                  makeSdkObservedFailure(
                    "setPresence",
                    action === "start" ? "startTyping" : "stopTyping",
                    failure
                  ),
              }).pipe(
                Effect.tap(() =>
                  observeSdkSuccess(
                    "setPresence",
                    action === "start" ? "startTyping" : "stopTyping"
                  )
                ),
                Effect.tapError(observeSdkFailure),
                Effect.mapError(
                  () =>
                    new ChannelUnavailableError({
                      provider: "photon",
                      operation: "setPresence",
                      reason: "transport",
                      retry: "backoff",
                    })
                )
              );
            })
          )
      ),
    })
  );

export const layerClientLive = (config: PhotonConfig) =>
  layerClient(config, liveFactory);
import { Schema } from "effect";

export const PhotonSdkOperation = Schema.Literals([
  "sendMessage",
  "setPresence",
]);
export type PhotonSdkOperation = typeof PhotonSdkOperation.Type;

export const PhotonSdkPhase = Schema.Literals([
  "acquire",
  "release",
  "resolveDirectSpace",
  "send",
  "startTyping",
  "stopTyping",
]);
export type PhotonSdkPhase = typeof PhotonSdkPhase.Type;

export const PhotonSdkTransportStatus = Schema.Int.check(
  Schema.isBetween({ minimum: 100, maximum: 599 })
);
export type PhotonSdkTransportStatus = typeof PhotonSdkTransportStatus.Type;

export class PhotonSdkObservedFailure extends Schema.TaggedErrorClass<PhotonSdkObservedFailure>()(
  "PhotonSdkObservedFailure",
  {
    operation: PhotonSdkOperation,
    phase: PhotonSdkPhase,
    transportStatus: Schema.Union([
      PhotonSdkTransportStatus,
      Schema.Literal("unknown"),
    ]),
    retryable: Schema.Union([Schema.Boolean, Schema.Literal("unknown")]),
  }
) {}
